# -*- coding: utf-8 -*-
"""内置网页界面（由 build_assets.py 从 web/index.html 自动生成，请勿手改）。

把界面内联进代码，是为了让上传/打包不再依赖 web 子目录：
  - GitHub 网页上传不支持子文件夹，扁平结构才能拖上去
  - PyInstaller 无需 --add-data，少一个出错环节
改界面请改 web/index.html，然后运行：python build_assets.py
"""

INDEX_HTML = '<!DOCTYPE html>\n<html lang="zh-CN">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width, initial-scale=1.0">\n<title>B站视频下载器</title>\n<style>\n  :root{\n    --bg:#f5f7fb; --card:#ffffff; --line:#e6e9f0; --text:#1f2533; --sub:#7a8499;\n    --brand:#2b7fff; --brand-d:#1d63d6; --green:#1faa59; --red:#e5484d;\n    --orange:#f0852b; --purple:#8b5cf6; --gray:#9aa3b2; --blue:#2b7fff;\n    --shadow:0 2px 12px rgba(20,30,60,.06);\n  }\n  *{box-sizing:border-box;margin:0;padding:0}\n  body{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI","PingFang SC","Microsoft YaHei",sans-serif;\n       background:var(--bg);color:var(--text);line-height:1.5;padding:24px;max-width:980px;margin:0 auto}\n  h1{font-size:22px;display:flex;align-items:center;gap:10px}\n  h1 .logo{width:30px;height:30px;border-radius:8px;background:linear-gradient(135deg,#2b7fff,#8b5cf6);\n           display:inline-flex;align-items:center;justify-content:center;color:#fff;font-size:16px}\n  .sub{color:var(--sub);font-size:13px;margin-top:2px}\n  .card{background:var(--card);border:1px solid var(--line);border-radius:14px;\n        padding:18px;box-shadow:var(--shadow);margin-top:16px}\n  .grid2{display:grid;grid-template-columns:1fr 1fr;gap:14px}\n  @media(max-width:680px){.grid2{grid-template-columns:1fr}}\n  label{display:block;font-size:13px;color:var(--sub);margin-bottom:5px;font-weight:600}\n  input,select,textarea{width:100%;border:1px solid var(--line);border-radius:9px;\n        padding:9px 11px;font-size:14px;background:#fff;color:var(--text);outline:none}\n  input:focus,select:focus,textarea:focus{border-color:var(--brand)}\n  textarea{min-height:120px;resize:vertical;font-family:inherit}\n  .row{display:flex;gap:10px;flex-wrap:wrap;align-items:flex-end}\n  .row > .col{flex:1;min-width:140px}\n  .btns{display:flex;gap:10px;flex-wrap:wrap;margin-top:14px}\n  button{cursor:pointer;border:none;border-radius:10px;padding:10px 18px;font-size:14px;font-weight:600;\n         transition:.15s;background:var(--brand);color:#fff}\n  button:hover{background:var(--brand-d)}\n  button.ghost{background:#eef2fb;color:var(--brand)}\n  button.ghost:hover{background:#e2e9f8}\n  button.danger{background:#fdecec;color:var(--red)}\n  button.danger:hover{background:#fbdada}\n  button.sm{padding:6px 12px;font-size:13px}\n  .check{display:flex;align-items:center;gap:8px;font-size:14px;color:var(--text);font-weight:500;cursor:pointer}\n  .check input{width:auto}\n  .hint{font-size:12px;color:var(--sub);margin-top:6px}\n  .tasks{margin-top:8px;display:flex;flex-direction:column;gap:12px}\n  .task{border:1px solid var(--line);border-radius:12px;padding:14px;background:#fff}\n  .task .top{display:flex;justify-content:space-between;align-items:flex-start;gap:10px}\n  .task .title{font-weight:600;font-size:14px;word-break:break-all}\n  .task .url{font-size:12px;color:var(--sub);word-break:break-all;margin-top:2px}\n  .badge{font-size:12px;font-weight:700;padding:3px 10px;border-radius:999px;white-space:nowrap}\n  .b-queued{background:#eef1f6;color:var(--gray)}\n  .b-downloading{background:#e6f0ff;color:var(--blue)}\n  .b-merging{background:#f1ecff;color:var(--purple)}\n  .b-finished{background:#e7f7ee;color:var(--green)}\n  .b-error{background:#fdecec;color:var(--red)}\n  .b-canceled{background:#fff1e6;color:var(--orange)}\n  .bar{height:8px;background:#eef1f6;border-radius:99px;margin-top:10px;overflow:hidden}\n  .bar > i{display:block;height:100%;background:linear-gradient(90deg,#2b7fff,#5b9bff);width:0;transition:width .4s}\n  .meta{display:flex;justify-content:space-between;font-size:12px;color:var(--sub);margin-top:7px;flex-wrap:wrap;gap:6px}\n  .empty{text-align:center;color:var(--sub);padding:30px 0;font-size:14px}\n  .err{color:var(--red);font-size:12px;margin-top:6px;word-break:break-all}\n  .toast{position:fixed;bottom:24px;left:50%;transform:translateX(-50%);background:#1f2533;color:#fff;\n         padding:10px 18px;border-radius:10px;font-size:14px;opacity:0;transition:.25s;pointer-events:none;z-index:9}\n  .toast.show{opacity:1}\n  details summary{cursor:pointer;color:var(--brand);font-size:13px;font-weight:600;margin-bottom:12px}\n  .tabs{display:flex;gap:8px;margin-bottom:14px;border-bottom:1px solid var(--line);padding-bottom:12px}\n  .tab{background:#f0f3fa;color:var(--sub)}\n  .tab.active{background:var(--brand);color:#fff}\n  .up-list{margin-top:10px;max-height:430px;overflow:auto;border:1px solid var(--line);border-radius:10px}\n  .up-item{display:flex;gap:10px;padding:10px 12px;border-bottom:1px solid var(--line);cursor:pointer;align-items:flex-start}\n  .up-item:hover{background:#f7f9fd}\n  .up-item:last-child{border-bottom:none}\n  .up-item input{margin-top:3px;width:auto}\n  .up-item .t{font-size:14px;font-weight:600;word-break:break-all}\n  .up-item .m{font-size:12px;color:var(--sub);margin-top:3px}\n</style>\n</head>\n<body>\n  <h1><span class="logo">B</span> B站视频下载器</h1>\n  <div class="sub">本地网页版 · 支持批量下载 / UP主内容勾选下载 · 自动合成 MP4（Windows / macOS 通用）</div>\n\n  <div class="card">\n    <details>\n      <summary>⚙️ 下载设置（画质 / cookie / 输出目录）</summary>\n      <div class="grid2">\n        <div>\n          <label>画质</label>\n          <select id="quality">\n            <option value="">最佳可用（默认）</option>\n            <option value="1080">1080P（需登录）</option>\n            <option value="720">720P</option>\n            <option value="480">480P</option>\n            <option value="360">360P</option>\n            <option value="audio">仅音频 (MP3)</option>\n          </select>\n        </div>\n        <div>\n          <label>输出目录</label>\n          <input id="output" placeholder="留空用默认 downloads 目录">\n        </div>\n      </div>\n      <div class="grid2" style="margin-top:14px">\n        <div>\n          <label>cookie 文件（Netscape 格式，高画质/会员必填）</label>\n          <input id="cookies" placeholder="如 C:/bili/cookies.txt">\n        </div>\n        <div>\n          <label>或读取浏览器登录态</label>\n          <select id="browser">\n            <option value="">不使用</option>\n            <option value="chrome">Chrome</option>\n            <option value="edge">Edge</option>\n            <option value="firefox">Firefox</option>\n          </select>\n        </div>\n      </div>\n      <div class="row" style="margin-top:14px">\n        <label class="check"><input type="checkbox" id="noSub" checked> 不下载字幕（体积更小）</label>\n        <label class="check"><input type="checkbox" id="playlist"> 下载整个合集/列表</label>\n        <div class="col" style="max-width:160px">\n          <input id="limit" placeholder="限速 如 2M">\n        </div>\n      </div>\n      <div style="margin-top:12px">\n        <label>✋ 或直接粘贴 Cookie（最省事：不用装插件、不用导出文件）</label>\n        <textarea id="cookieText" rows="3" placeholder="SESSDATA=xxxxxxxx; bili_jct=yyyy; DedeUserID=123456"\n          style="width:100%;min-height:62px;font-family:ui-monospace,Menlo,monospace;font-size:12px;line-height:1.5;padding:8px 10px;border:1px solid #d0d7de;border-radius:8px;background:#fff;color:#1f2328;resize:vertical"></textarea>\n        <div class="btns" style="margin-top:8px">\n          <button class="ghost sm" id="pasteCookie">📋 保存这份 Cookie 并设为默认</button>\n          <span class="hint" id="cookieMsg"></span>\n        </div>\n      </div>\n      <div class="hint" style="margin-top:10px">\n        <strong>怎么拿到 Cookie？</strong>浏览器登录 bilibili.com → 按 <code>F12</code>（Mac 用 <code>⌥⌘C</code>）打开开发者工具 → 切到「网络 / Network」→ 刷新页面 → 点第一个请求 → 在「请求标头 / Request Headers」里复制 <code>Cookie:</code> 后那一整串，粘贴到上面框里保存即可。<br>\n        高画质 / 大会员 / 番剧 / <strong>UP主列表</strong>都需要登录态。除粘贴外，也可填 cookie 文件路径（Netscape 格式）或选择上面的浏览器登录态。\n      </div>\n      <div class="btns"><button class="ghost sm" id="saveCfg">💾 保存为默认设置（下次启动自动载入）</button></div>\n    </details>\n  </div>\n\n  <div class="card">\n    <div class="tabs">\n      <button class="tab active" id="tabLink">🔗 视频链接</button>\n      <button class="tab" id="tabUp">👤 UP主视频</button>\n    </div>\n\n    <div id="paneLink">\n      <label>视频链接（每行一个，支持 BV号 / 链接 / 短链）</label>\n      <textarea id="urls" placeholder="https://www.bilibili.com/video/BV1GJ411x7h7&#10;BV1xx411c7mD&#10;https://b23.tv/xxxxx"></textarea>\n      <div class="btns">\n        <button id="start">⬇️ 开始下载</button>\n        <button class="ghost" id="clear">🧹 清空已完成</button>\n        <button class="ghost" id="open">📂 打开输出文件夹</button>\n      </div>\n    </div>\n\n    <div id="paneUp" style="display:none">\n      <div class="row">\n        <div class="col" style="flex:3">\n          <label>UP主空间链接 或 UID</label>\n          <input id="upUrl" placeholder="https://space.bilibili.com/546195  或直接填 546195">\n        </div>\n        <div class="col" style="max-width:130px">\n          <label>获取数量</label>\n          <input id="upLimit" value="30">\n        </div>\n        <button id="fetchList">🔍 获取视频列表</button>\n      </div>\n      <div class="hint" id="upHint">按发布时间拉取该 UP 主最新视频，获取后逐条勾选再下载；也支持合集 / 收藏夹 / 系列链接。<strong>注意：B站对空间列表有风控（错误 352），通常需要先在上方「下载设置」里配置 cookie。</strong></div>\n\n      <div id="upListWrap" style="display:none">\n        <div style="display:flex;justify-content:space-between;align-items:center;margin-top:14px;gap:10px;flex-wrap:wrap">\n          <span class="hint" id="upCount" style="margin:0"></span>\n          <div class="btns" style="margin:0">\n            <button class="ghost sm" id="selAll">全选</button>\n            <button class="ghost sm" id="selNone">全不选</button>\n            <button class="sm" id="dlSelected">⬇️ 下载选中</button>\n          </div>\n        </div>\n        <div class="up-list" id="upList"></div>\n      </div>\n    </div>\n  </div>\n\n  <div class="card">\n    <div style="display:flex;justify-content:space-between;align-items:center">\n      <label style="margin:0">下载任务</label>\n      <span class="hint" id="countHint"></span>\n    </div>\n    <div class="tasks" id="tasks"><div class="empty">还没有任务，粘贴链接或勾选 UP 主视频后开始下载。</div></div>\n  </div>\n\n<script>\nconst $ = id => document.getElementById(id);\nlet toastTimer;\nfunction toast(msg){\n  const t = $(\'toast\'); t.textContent = msg; t.classList.add(\'show\');\n  clearTimeout(toastTimer); toastTimer = setTimeout(()=>t.classList.remove(\'show\'),2200);\n}\n\nfunction fmtSize(b){ if(!b) return \'\'; const u=[\'B\',\'KB\',\'MB\',\'GB\']; let i=0; while(b>=1024&&i<u.length-1){b/=1024;i++;} return b.toFixed(1)+u[i]; }\nfunction fmtSpeed(b){ if(!b) return \'\'; return fmtSize(b)+\'/s\'; }\nfunction fmtEta(s){ if(!s||s<0) return \'\'; const m=Math.floor(s/60),x=s%60; return `${m}:${String(x).padStart(2,\'0\')}`; }\nfunction esc(s){ return (s||\'\').replace(/[&<>"]/g,c=>({\'&\':\'&amp;\',\'<\':\'&lt;\',\'>\':\'&gt;\',\'"\':\'&quot;\'}[c])); }\nfunction fmtDur(s){ if(!s) return \'-\'; const h=Math.floor(s/3600),m=Math.floor(s%3600/60),x=s%60;\n  return h? `${h}:${String(m).padStart(2,\'0\')}:${String(x).padStart(2,\'0\')}` : `${m}:${String(x).padStart(2,\'0\')}`; }\nfunction fmtView(n){ if(!n) return \'-\'; return n>=10000 ? (n/10000).toFixed(1)+\'万\' : String(n); }\nfunction fmtDate(d){ if(!d||String(d).length!==8) return \'-\'; d=String(d); return `${d.slice(0,4)}-${d.slice(4,6)}-${d.slice(6,8)}`; }\n\nconst STATUS_TEXT = {queued:\'排队中\',downloading:\'下载中\',merging:\'合成中\',finished:\'已完成\',error:\'失败\',canceled:\'已取消\'};\n\nfunction collectOptions(){\n  const q = $(\'quality\').value;\n  return {\n    quality: (q && q!==\'audio\') ? parseInt(q,10) : null,\n    audio_only: q===\'audio\',\n    no_sub: $(\'noSub\').checked,\n    noplaylist: !$(\'playlist\').checked,\n    cookies: $(\'cookies\').value.trim() || \'\',\n    cookies_from_browser: $(\'browser\').value || \'\',\n    limit: $(\'limit\').value.trim() || \'\',\n    output: $(\'output\').value.trim() || \'\'\n  };\n}\n\n$(\'tabLink\').onclick = ()=>{\n  $(\'paneLink\').style.display=\'\'; $(\'paneUp\').style.display=\'none\';\n  $(\'tabLink\').classList.add(\'active\'); $(\'tabUp\').classList.remove(\'active\');\n};\n$(\'tabUp\').onclick = ()=>{\n  $(\'paneLink\').style.display=\'none\'; $(\'paneUp\').style.display=\'\';\n  $(\'tabUp\').classList.add(\'active\'); $(\'tabLink\').classList.remove(\'active\');\n};\n\nlet upVideos = [];\n$(\'fetchList\').onclick = async ()=>{\n  const url = $(\'upUrl\').value.trim();\n  if(!url){ toast(\'请填写 UP主空间链接或 UID\'); return; }\n  $(\'upHint\').textContent = \'正在获取视频列表…\';\n  $(\'upListWrap\').style.display=\'none\';\n  const r = await fetch(\'/api/up/list\',{method:\'POST\',headers:{\'Content-Type\':\'application/json\'},\n    body:JSON.stringify({url, limit: parseInt($(\'upLimit\').value,10)||30,\n      options:{cookies: $(\'cookies\').value.trim(), cookies_from_browser: $(\'browser\').value}})});\n  const j = await r.json();\n  if(j.error){ $(\'upHint\').textContent = \'⚠️ \' + j.error; return; }\n  upVideos = j.videos || [];\n  $(\'upHint\').textContent = j.uploader ? (\'UP主：\' + j.uploader) : \'\';\n  renderUp();\n  $(\'upListWrap\').style.display=\'\';\n};\n\nfunction renderUp(){\n  $(\'upCount\').textContent = `共 ${upVideos.length} 个视频`;\n  $(\'upList\').innerHTML = upVideos.map((v,i)=>`\n    <label class="up-item">\n      <input type="checkbox" data-i="${i}">\n      <div>\n        <div class="t">${esc(v.title)}</div>\n        <div class="m">🕒 ${fmtDur(v.duration)} · ▶ ${fmtView(v.view_count)} · 📅 ${fmtDate(v.upload_date)} · ${esc(v.bvid)}</div>\n      </div>\n    </label>`).join(\'\');\n}\n\n$(\'selAll\').onclick = ()=>document.querySelectorAll(\'#upList input[type=checkbox]\').forEach(b=>b.checked=true);\n$(\'selNone\').onclick = ()=>document.querySelectorAll(\'#upList input[type=checkbox]\').forEach(b=>b.checked=false);\n\n$(\'dlSelected\').onclick = async ()=>{\n  const picked = [...document.querySelectorAll(\'#upList input[type=checkbox]\')]\n    .filter(b=>b.checked).map(b=>upVideos[+b.dataset.i]).filter(v=>v && v.url);\n  if(!picked.length){ toast(\'请先勾选要下载的视频\'); return; }\n  const r = await fetch(\'/api/add\',{method:\'POST\',headers:{\'Content-Type\':\'application/json\'},\n    body:JSON.stringify({urls: picked.map(v=>v.url), options: collectOptions()})});\n  const j = await r.json();\n  toast(`已添加 ${j.ids.length} 个下载任务`);\n};\n\n$(\'start\').onclick = async ()=>{\n  const raw = $(\'urls\').value.trim();\n  if(!raw){ toast(\'请先粘贴链接\'); return; }\n  const urls = raw.split(/\\r?\\n/).map(s=>s.trim()).filter(Boolean);\n  const r = await fetch(\'/api/add\',{method:\'POST\',headers:{\'Content-Type\':\'application/json\'},\n    body:JSON.stringify({urls,options:collectOptions()})});\n  const j = await r.json();\n  $(\'urls\').value=\'\';\n  toast(`已添加 ${j.ids.length} 个任务`);\n};\n\n$(\'clear\').onclick = async ()=>{ await fetch(\'/api/clear\',{method:\'POST\'}); };\n$(\'open\').onclick = async ()=>{ const r=await fetch(\'/api/open\'); const j=await r.json(); if(!j.ok) toast(\'打开失败：\'+j.error); };\n\nasync function refresh(){\n  try{\n    const r = await fetch(\'/api/tasks\'); const j = await r.json();\n    render(j.tasks||[]);\n    $(\'countHint\').textContent = j.ffmpeg ? \'\' : \'⚠️ 未找到 ffmpeg\';\n  }catch(e){}\n}\n\nfunction render(tasks){\n  const box = $(\'tasks\');\n  if(!tasks.length){ box.innerHTML=\'<div class="empty">还没有任务，粘贴链接或勾选 UP 主视频后开始下载。</div>\'; return; }\n  box.innerHTML = tasks.map(t=>{\n    const pct = t.status===\'finished\'?100:t.progress;\n    const cls = \'b-\'+t.status;\n    const meta = t.status===\'downloading\'\n      ? `${fmtSize(t.downloaded)} / ${fmtSize(t.total)} · ${fmtSpeed(t.speed)} · 剩余 ${fmtEta(t.eta)}`\n      : (t.total? `${fmtSize(t.total)}`:\'\');\n    const cancelBtn = (t.status===\'downloading\'||t.status===\'queued\'||t.status===\'merging\')\n      ? `<button class="danger sm" onclick="cancel(\'${t.id}\')">取消</button>` : \'\';\n    return `<div class="task">\n      <div class="top">\n        <div>\n          <div class="title">${esc(t.title)}</div>\n          <div class="url">${esc(t.url)}</div>\n        </div>\n        <div style="display:flex;gap:8px;align-items:center">\n          <span class="badge ${cls}">${STATUS_TEXT[t.status]||t.status}</span>\n          ${cancelBtn}\n        </div>\n      </div>\n      <div class="bar"><i style="width:${pct}%"></i></div>\n      <div class="meta"><span>${meta}</span><span>${pct.toFixed(1)}%</span></div>\n      ${t.error?`<div class="err">⚠️ ${esc(t.error)}</div>`:\'\'}\n    </div>`;\n  }).join(\'\');\n}\n\nasync function cancel(id){\n  await fetch(\'/api/cancel\',{method:\'POST\',headers:{\'Content-Type\':\'application/json\'},body:JSON.stringify({id})});\n}\n\n/* ---------- 默认设置记忆（cookie 等） ---------- */\n(async ()=>{\n  try{\n    const r = await fetch(\'/api/config\'); const c = await r.json();\n    if(c.cookies) $(\'cookies\').value = c.cookies;\n    if(c.cookies_from_browser) $(\'browser\').value = c.cookies_from_browser;\n    if(c.output) $(\'output\').value = c.output;\n  }catch(e){}\n})();\n\n$(\'saveCfg\').onclick = async ()=>{\n  await fetch(\'/api/config\',{method:\'POST\',headers:{\'Content-Type\':\'application/json\'},\n    body:JSON.stringify({cookies:$(\'cookies\').value.trim(),\n      cookies_from_browser:$(\'browser\').value, output:$(\'output\').value.trim()})});\n  toast(\'已保存为默认设置，下次启动自动载入\');\n};\n\n/* ---------- 粘贴 Cookie 并设为默认 ---------- */\n$(\'pasteCookie\').onclick = async ()=>{\n  const t = $(\'cookieText\').value.trim();\n  if(!t){ $(\'cookieMsg\').textContent = \'请先把 Cookie 粘贴到上面的框里\'; return; }\n  $(\'cookieMsg\').textContent = \'保存中…\';\n  try{\n    const r = await (await fetch(\'/api/cookies\',{method:\'POST\',headers:{\'Content-Type\':\'application/json\'},\n      body:JSON.stringify({text:t})})).json();\n    if(r.ok){\n      $(\'cookies\').value = r.path;\n      $(\'cookieMsg\').textContent = `✅ 已保存 ${r.count} 条并设为默认`\n        + (r.has_sessdata ? \'（含 SESSDATA，登录态有效）\' : \'（⚠️ 未见 SESSDATA，可能无效）\');\n      toast(\'Cookie 已保存并设为默认\');\n    }else{\n      $(\'cookieMsg\').textContent = \'❌ \' + r.error;\n    }\n  }catch(e){ $(\'cookieMsg\').textContent = \'❌ 请求失败：\' + e; }\n};\n\nrefresh();\nsetInterval(refresh, 1500);\n</script>\n<div class="toast" id="toast"></div>\n</body>\n</html>\n'
